begin;
set local search_path = public, extensions;
select plan(28);
select ok(not has_function_privilege('anon', 'public.consume_otp_limit(text,text,text,uuid)', 'EXECUTE'), 'anon cannot bypass OTP gate');
select ok(not has_function_privilege('authenticated', 'public.consume_otp_limit(text,text,text,uuid)', 'EXECUTE'), 'users cannot alter OTP attempts');
select ok(has_function_privilege('service_role', 'public.consume_otp_limit(text,text,text,uuid)', 'EXECUTE'), 'server can consume OTP limits');
select is(public.consume_otp_limit('request', repeat('a',64), repeat('b',64), '30000000-0000-4000-8000-000000000001')->>'allowed', 'true', 'initial request accepted');
select is(public.consume_otp_limit('request', repeat('a',64), repeat('b',64), '30000000-0000-4000-8000-000000000002')->>'allowed', 'false', 'resend cooldown enforced');
select is(public.consume_otp_limit('verify', repeat('a',64), repeat('b',64), '30000000-0000-4000-8000-000000000001')->>'allowed', 'true', 'first attempt accepted');
select is(public.consume_otp_limit('verify', repeat('a',64), repeat('b',64), '30000000-0000-4000-8000-000000000001')->>'allowed', 'true', 'second attempt accepted');
select is(public.consume_otp_limit('verify', repeat('a',64), repeat('b',64), '30000000-0000-4000-8000-000000000001')->>'allowed', 'true', 'third attempt accepted');
select is(public.consume_otp_limit('verify', repeat('a',64), repeat('b',64), '30000000-0000-4000-8000-000000000001')->>'allowed', 'false', 'fourth attempt rejected');
update private.otp_challenges set sent_at = now() - interval '61 seconds' where email_hash = repeat('a',64);
select is(public.consume_otp_limit('request', repeat('a',64), repeat('b',64), '30000000-0000-4000-8000-000000000002')->>'allowed', 'true', 'resend rotates challenge');
select is(public.consume_otp_limit('verify', repeat('a',64), repeat('b',64), '30000000-0000-4000-8000-000000000001')->>'allowed', 'false', 'old challenge rejected');
update private.otp_challenges set expires_at = now() - interval '1 second' where email_hash = repeat('a',64);
select is(public.consume_otp_limit('verify', repeat('a',64), repeat('b',64), '30000000-0000-4000-8000-000000000002')->>'allowed', 'false', 'expired challenge rejected');
update private.otp_challenges set sent_at = now() - interval '61 seconds' where email_hash = repeat('a',64);
update private.auth_rate_limits set requests = 5 where key = 'email:' || repeat('a',64);
select is(public.consume_otp_limit('request', repeat('a',64), repeat('b',64), '30000000-0000-4000-8000-000000000003')->>'allowed', 'false', 'sixth account send in an hour rejected');
update private.auth_rate_limits set requests = 20 where key = 'ip:' || repeat('b',64);
select is(public.consume_otp_limit('request', repeat('c',64), repeat('b',64), '30000000-0000-4000-8000-000000000003')->>'allowed', 'false', 'twenty-first IP send in an hour rejected');
select is(public.consume_otp_limit('request', repeat('d',64), repeat('e',64), '30000000-0000-4000-8000-000000000004')->>'allowed', 'true', 'independent account/IP accepted');
select is(public.consume_otp_limit('complete', repeat('d',64), repeat('e',64), '30000000-0000-4000-8000-000000000004')->>'allowed', 'true', 'successful challenge consumed');
select is(public.consume_otp_limit('verify', repeat('d',64), repeat('e',64), '30000000-0000-4000-8000-000000000004')->>'allowed', 'false', 'consumed challenge cannot replay');
select is(public.consume_otp_limit('verify', repeat('f',64), repeat('e',64), '30000000-0000-4000-8000-000000000004')->>'allowed', 'false', 'challenge is bound to account');
select ok(not has_table_privilege('authenticated', 'private.otp_challenges', 'SELECT'), 'users cannot inspect challenge hashes');
select ok(not has_table_privilege('service_role', 'private.auth_rate_limits', 'SELECT'), 'server uses narrow RPC rather than direct table grants');

insert into auth.users (id, email, email_confirmed_at) values
  ('40000000-0000-4000-8000-000000000001', 'bootstrap@budgetly.test', now());
set local role authenticated;
set local request.jwt.claims = '{"sub":"40000000-0000-4000-8000-000000000001","role":"authenticated"}';
select lives_ok($$select public.ensure_personal_workspace()$$, 'verified user provisions personal workspace');
select lives_ok($$select public.ensure_personal_workspace()$$, 'provisioning retry is idempotent');
select lives_ok($$set constraints all immediate$$, 'deferred integrity checks work under the authenticated caller');
select is((select count(*)::integer from public.workspaces), 1, 'only one own personal workspace');
select is((select type from public.workspaces), 'personal', 'no automatic household access');
reset role;
set constraints all immediate;
select ok(not has_function_privilege('anon', 'public.ensure_personal_workspace()', 'EXECUTE'), 'anonymous provisioning denied');
insert into auth.users (id, email) values ('40000000-0000-4000-8000-000000000002', 'unverified@budgetly.test');
set local role authenticated;
set local request.jwt.claims = '{"sub":"40000000-0000-4000-8000-000000000002","role":"authenticated"}';
select throws_ok($$select public.ensure_personal_workspace()$$, '42501', null, 'unverified identity cannot provision');
reset role;
update public.profiles set deleted_at = now() where id = '40000000-0000-4000-8000-000000000001';
set local role authenticated;
set local request.jwt.claims = '{"sub":"40000000-0000-4000-8000-000000000001","role":"authenticated"}';
select throws_ok($$select public.ensure_personal_workspace()$$, '42501', null, 'deleted profile cannot be reactivated by sign-in');
reset role;
select * from finish();
rollback;
